from openpyxl import load_workbook

# Load the workbook and select the sheet
wb = load_workbook('input.xlsx')
ws = wb['Sheet1']

# Iterate through the rows to find all part numbers matching the pattern '400-...-A'
part_numbers = []
for row in ws.iter_rows(min_row=1, max_col=1, values_only=True):
    cell_value = row[0]
    if cell_value and cell_value.startswith('400-') and cell_value.endswith('-A'):
        part_numbers.append(cell_value)

# Iterate through the rows again to find the rows to delete
rows_to_delete = []
current_index = 0
for i, row in enumerate(ws.iter_rows(min_row=1, min_col=1, max_col=1, values_only=True), start=1):
    if row[0] and row[0].startswith('400-') and row[0].endswith('-A'):
        # Find the next part number after this one
        next_part = None
        for part in part_numbers:
            if part == row[0]:
                next_part = None
            elif part > row[0]:
                next_part = part
                break
        if next_part:
            # Find the range of rows to delete
            start_row = i
            end_row = None
            for j in range(i + 1, len(ws['A']) + 1):
                if ws['A'][j - 1].value == next_part:
                    end_row = j - 1
                    break
            if end_row:
                rows_to_delete.extend(range(start_row, end_row + 1))

# Delete the rows
for row in reversed(rows_to_delete):
    ws.delete_rows(row)

# Write the computed values back to the output
wb.save('output.xlsx')
