from openpyxl import load_workbook
from openpyxl.styles import Font, Alignment, Border, Side

# Load the workbook and select the active sheet
wb = load_workbook('input.xlsx')
ws = wb.active

# Set the headers and apply formatting
headers = ['Calling Party Number', 'Original Called Party Number', 'Final Called Party Number']
for col_num, header in enumerate(headers, 1):
    ws.cell(row=4, column=col_num).value = header
    ws.cell(row=4, column=col_num).font = Font(bold=True)
    ws.cell(row=4, column=col_num).alignment = Alignment(wrap_text=True)

# Apply borders to the headers
border = Border(top=Side(style='thin'), left=Side(style='thin'), right=Side(style='thin'), bottom=Side(style='thin'))
for col_num in range(1, len(headers) + 1):
    ws.cell(row=4, column=col_num).border = border

# Apply wrap text to row 4
for col_num in range(1, len(headers) + 1):
    ws.cell(row=4, column=col_num).alignment = Alignment(wrap_text=True)

# Disable values and borders for column G (column 7)
for row in ws.iter_rows(min_row=1, max_row=ws.max_row, min_col=7, max_col=7):
    for cell in row:
        cell.value = None
        cell.border = None

# Count transfers from operator (column D) with transfer number 5551234
operator_transfer_number = '5551234'
transfer_counts = {}

# Iterate through rows to count transfers
for row in ws.iter_rows(min_row=5, max_row=ws.max_row, min_col=4, max_col=5):
    operator_number = row[0].value
    called_party_number = row[1].value
    if operator_number == operator_transfer_number:
        if called_party_number not in transfer_counts:
            transfer_counts[called_party_number] = 1
        else:
            transfer_counts[called_party_number] += 1

# Fill the computed values in column H
for row in ws.iter_rows(min_row=5, max_row=ws.max_row, min_col=8, max_col=8):
    for cell in row:
        # Find the last transfer row and set the count
        if cell.row == ws.max_row:
            # Find the last transfer in the list
            last_transfer_row = None
            for r in range(5, ws.max_row + 1):
                if ws.cell(row=r, column=4).value == operator_transfer_number:
                    last_transfer_row = r
            if last_transfer_row:
                transfer_number = ws.cell(row=last_transfer_row, column=5).value
                cell.value = transfer_counts.get(transfer_number, 0)
            else:
                cell.value = 0

# Save the modified workbook
wb.save('output.xlsx')
